Definition chk (x : Z) : bool :=
  let mk := MK x in
  (-307 <=? mk) && (mk <=? 325) &&
  match nth_error TABF (Z.to_nat (343 + mk)), nth_error TABE (Z.to_nat (343 + mk)) with
  | Some c, Some ce => (2 ^ 63 <=? c) && (c <? 2 ^ 64) && (ce <? 2 ^ 32) && (0 <=? ce) && (-59 <=? 4 - x + s32 ce) && (4 - x + s32 ce <=? -56)
  | _, _ => false
  end.
